const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',person:'M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-3a8 8 0 0 1 16 0v3',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4M18 4h4',device:'M7 2h10a2 2 0 0 1 2 2v16a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2ZM10 18h4M14 8a2 2 0 1 1-4 0 2 2 0 0 1 4 0',arrow:'m9 5 7 7-7 7',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',expand:'M8 3H3v5M16 3h5v5M21 16v5h-5M3 16v5h5',walk:'M15 4a1 1 0 1 1-2 0 1 1 0 0 1 2 0M8 21l4-7 3 3v4M6 12l3-4 4 1 3 5h4M13 9l-1 5-4-2',food:'M5 2v8M2 2v5a3 3 0 0 0 6 0V2M5 10v12M18 22V2c-5 2-5 11 0 11',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',check:'m5 12 4 4L19 6',smile:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M8 9h.01M16 9h.01M7 14c2 4 8 4 10 0',warning:'m12 3 10 18H2ZM12 9v5M12 17h.01',heart:'M20 4c-4-3-8 2-8 2S8 1 4 4c-7 5 8 17 8 17S27 9 20 4',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.01',phone:'M7 3H3c-2 11 7 20 18 18v-4l-5-2-2 3a15 15 0 0 1-8-8l3-2Z',send:'m3 3 19 9-19 9 4-9ZM7 12h15',back:'m15 5-7 7 7 7',location:'M19 9c0 6-7 13-7 13S5 15 5 9a7 7 0 0 1 14 0ZM14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0'};
const ico=(n)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.heart}"/></svg>`;
const nav=[['inicio','home','Inicio'],['alertas','bell','Alertas'],['historial','clock','Historial'],['persona','person','Persona'],['asistente','spark','Asistente IA'],['dispositivo','device','Dispositivo']];
const events=[{time:'10:32',title:'Se levantó del sofá',desc:'Movimiento habitual · Sala',icon:'walk',tone:'green',cat:'Movimiento'},{time:'09:48',title:'Hora de desayunar',desc:'Alimentación habitual',icon:'food',tone:'orange',cat:'Alimentación'},{time:'08:15',title:'Un paseo por la sala',desc:'Actividad ligera · 5 min',icon:'walk',tone:'purple',cat:'Movimiento'},{time:'06:24',title:'Descansó bien',desc:'Sueño tranquilo · 7 h 20 min',icon:'moon',tone:'green',cat:'Sueño'}];
let filter='Todos',tab='Información',alertFilter='Todas';let chatMessages=[];const settings={notifications:true,sound:false,privacy:true};
function go(page){location.hash=page}function notify(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3000)}function modal(title,text){document.querySelector('#modal-content').innerHTML=`<h2>${title}</h2><p>${text}</p>`;document.querySelector('#modal').showModal()}
function heading(title,sub,extra=''){return `<div class="heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${extra}</div>`}function button(text,page,icon='arrow',type=''){return `<button class="button ${type}" onclick="go('${page}')">${ico(icon)}${text}</button>`}const chipPerson=`<button class="person-chip" onclick="go('persona')"><div class="avatar">M</div><div><b>María García</b><small>Tu persona de cuidado</small></div>${ico('arrow')}</button>`;
function camera(big=false){return `<div class="camera ${big?'wide-camera':''}" id="camera"><img src="assets/living-room.png" alt="Escena simulada de María leyendo en la sala"><span class="live"><span class="live-dot"></span> Vista de demostración</span><button class="expand" aria-label="Ampliar o cerrar vista" onclick="document.querySelector('#camera').classList.toggle('fullscreen-camera')">${ico('expand')}</button><div class="caption">Sala de estar<small>Cámara 01 · Cerca Home</small></div></div>`}
function activity(e,history=false){return `<div class="activity-row ${history?'history-row':''}" tabindex="0" role="button" onclick="eventDetail('${e.time}')" onkeydown="if(event.key==='Enter')eventDetail('${e.time}')"><div class="round-icon tone-${e.tone}">${ico(e.icon)}</div><div><b>${e.title}</b><small>${e.desc}</small></div><span class="time">${e.time}</span></div>`}function eventDetail(time){const e=events.find(x=>x.time===time);modal(e.title,`Hoy, ${e.time}. ${e.desc}. Este evento forma parte del historial simulado de María para la presentación de Cerca.`)}
function home(){return heading('Hola, Karol <em>☀</em>','La tranquilidad de saber cómo está María.',chipPerson)+`<div class="grid"><div class="stack"><section class="wellbeing"><div class="status-icon">${ico('smile')}</div><div><div class="eyebrow">EL DÍA DE MARÍA, EN CALMA</div><h2>Todo está bien</h2><p>No se han detectado cambios relevantes en su comportamiento.</p></div><span class="checkstamp">${ico('check')}</span></section><section class="card"><div class="card-heading"><h2>Una mirada a su día</h2><span class="badge"><span class="live-dot"></span> Sala</span></div>${camera()}<div class="camera-meta"><span>Persona detectada</span><span class="badge">Movimiento habitual</span></div>${button('Ver monitoreo','monitoreo','eye','wide')}</section><button class="device-status" onclick="go('dispositivo')"><span class="round-icon">${ico('device')}</span><span style="text-align:left"><b>Tu dispositivo está conectado</b><small>Última actualización hace 2 min</small></span><span class="right">${ico('arrow')}</span></button></div><div class="stack"><section class="card"><div class="card-heading"><h2>Actividad reciente</h2><button class="link" onclick="go('historial')">Ver todo ${ico('arrow')}</button></div>${events.map(e=>activity(e)).join('')}</section><section class="card ai-card"><div class="card-heading" style="margin-bottom:0"><h2 style="display:flex;align-items:center;gap:10px"><span class="ai-icon">${ico('spark')}</span> Un poco más de claridad</h2></div><p>Comprende su actividad y resuelve tus dudas con el asistente de Cerca.</p><button class="link" onclick="go('asistente')">Conversar con el asistente ${ico('arrow')}</button></section><div><div class="card-heading" style="margin-bottom:0"><h2 class="section-title">Su día, en un vistazo</h2><span class="muted" style="font-size:10px">HOY</span></div><div class="mini-stats"><div class="stat"><span class="label">${ico('moon')} Descanso</span><strong>7 h 20</strong><small>Dentro de lo habitual</small></div><div class="stat"><span class="label">${ico('walk')} Actividad</span><strong>32 min</strong><small>Movimiento ligero</small></div><div class="stat"><span class="label">${ico('heart')} Bienestar</span><strong>Estable</strong><small>Sin cambios recientes</small></div></div></div></div></div>`}
const alerts=[['urgent','Urgente','Posible señal de malestar','10:32 · 8 min','Se observaron inquietud y movimientos repetitivos.','warning'],['attention','Atención','Cambio de comportamiento','08:15 · 5 min','Actividad diferente a su patrón habitual.','warning'],['normal','Normal','Comportamiento habitual','06:24 · 12 min','María está descansando con tranquilidad.','check']];
function alertPage(){return heading('Alertas','Te avisamos cuando algo merece tu atención.')+`<div class="chips">${['Todas','Urgente','Atención','Normal'].map(x=>`<button class="chip ${alertFilter===x?'selected':''}" onclick="alertFilter='${x}';render()">${x}</button>`).join('')}</div><div class="muted">Escenarios de ejemplo para explorar durante la presentación.</div>${alerts.filter(a=>alertFilter==='Todas'||alertFilter===a[1]).map((a)=>`<article class="alert-item ${a[0]}" role="button" tabindex="0" onclick="go('detalle-${a[0]}')" onkeydown="if(event.key==='Enter')go('detalle-${a[0]}')"><span class="round-icon">${ico(a[5])}</span><div><span class="urgent-label">${a[1]}</span><h3>${a[2]}</h3><p>${a[4]}</p><p style="font-size:11px;margin-top:8px">${a[3]}</p></div><span class="right">${ico('arrow')}</span></article>`).join('')}`}
function detail(type){const a=alerts.find(a=>a[0]===type)||alerts[0];return `<button class="link back" onclick="go('alertas')">${ico('back')} Todas las alertas</button>`+heading(a[2],`Hoy, ${a[3]} · Evento de demostración`)+`<div class="grid"><div class="stack"><section class="card"><div class="card-heading"><h2>Qué se observó</h2><span class="badge">${a[1]}</span></div><ul class="detail-list">${(type==='normal'?['Descanso tranquilo','Postura habitual','Sin cambios de actividad']:['Mayor inquietud de lo habitual','Movimientos repetitivos durante 8 minutos','Cambios en la postura corporal']).map(s=>`<li>${s}</li>`).join('')}</ul></section>${camera()}${button('Ver monitoreo','monitoreo','eye','wide')}</div><div class="stack"><section class="card ai-card"><span class="ai-icon">${ico('spark')}</span><h2 style="margin-top:15px">Una orientación para ti</h2><p>${type==='normal'?'La actividad de María coincide con su rutina de descanso. Puedes consultar los eventos del día en su historial.':'Estos cambios pueden tener distintas causas. Acércate a María y pregúntale cómo se siente para comprender mejor la situación.'}</p>${button('Consultar al asistente','asistente','spark','secondary wide')}</section><section class="card"><h2>Estar cerca también es escuchar</h2><p class="subtitle" style="margin:12px 0 20px">Puedes ponerte en contacto con tu familiar.</p><button class="button wide" onclick="modal('Contactar a María','En la app final, desde aquí podrías iniciar una llamada. En esta presentación no se realiza ninguna llamada real.')">${ico('phone')} Contactar</button></section></div></div>`}
function monitor(){return heading('Monitoreo','Un espacio para sentirte cerca, estés donde estés.',`<span class="badge">${ico('wifi')} Dispositivo conectado</span>`)+`<div class="grid"><section class="card">${camera(true)}<div class="camera-meta"><span>${ico('location')} Sala de estar</span><span class="badge">Movimiento habitual</span></div><button class="button wide" onclick="document.querySelector('#camera').classList.toggle('fullscreen-camera')">${ico('expand')} Pantalla completa</button></section><div class="stack"><section class="card"><div class="card-heading"><h2>Eventos recientes</h2><button class="link" onclick="go('historial')">Ver historial</button></div>${events.slice(0,3).map(e=>activity(e)).join('')}</section><section class="card ai-card"><h2>Su privacidad, primero</h2><p>Esta vista utiliza una imagen de demostración. No hay ninguna cámara conectada.</p><button class="link" onclick="go('dispositivo')">Ajustes del dispositivo ${ico('arrow')}</button></section></div></div>`}
function history(){const list=events.filter(e=>filter==='Todos'||e.cat===filter);return heading('Su historia, día a día','Consulta los momentos y las rutinas de María.')+`<div class="chips">${['Todos','Movimiento','Alimentación','Sueño'].map(x=>`<button class="chip ${filter===x?'selected':''}" onclick="filter='${x}';render()">${x}</button>`).join('')}</div><section class="card"><div class="card-heading"><h2>Hoy, 22 de septiembre</h2><span class="muted">${list.length} eventos</span></div>${list.map(e=>activity(e,true)).join('')}</section><p class="muted" style="margin-top:20px">Estás viendo todos los eventos de este día de demostración.</p>`}
function profile(){let rows=tab==='Información'?[['Fecha de nacimiento','12 de marzo de 1948 · 78 años'],['Género','Femenino'],['Contacto principal','Karol García · Hija'],['Espacio habitual','Sala de estar']]:tab==='Salud'?[['Antecedentes de ejemplo','Diabetes tipo 2'],['Condición registrada','Hipertensión'],['Alergias','Penicilina'],['Nota','Información ficticia para la presentación.']]:[['Rutina de descanso','22:00 a 06:30'],['Actividad habitual','Lectura y caminatas en casa'],['Horario de desayuno','09:00 a 10:00'],['Preferencias','Espacios tranquilos y luz natural']];return heading('La persona que importa','Su información, siempre a la mano.')+`<div class="grid"><section class="card"><div class="profile-header"><div class="avatar">M</div><div><h2>María García</h2><p class="subtitle">78 años · Tu mamá</p></div></div><div class="chips">${['Información','Salud','Comportamiento'].map(x=>`<button class="chip ${tab===x?'selected':''}" onclick="tab='${x}';render()">${x}</button>`).join('')}</div><ul class="detail-list">${rows.map(r=>`<li><span>${r[0]}</span>${r[1]}</li>`).join('')}</ul></section><div class="stack"><section class="card"><h2>Su círculo de cuidado</h2><div class="activity-row"><div class="avatar">K</div><div><b>Karol García</b><small>Hija · Contacto principal</small></div><span class="badge right">Tú</span></div></section><section class="card ai-card"><h2>Cuidar empieza por conocer</h2><p>Las rutinas de María ayudan a dar contexto a los cambios de su día.</p><button class="link" onclick="go('historial')">Explorar su actividad ${ico('arrow')}</button></section></div></div>`}
function escapeText(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function ask(q){if(!q.trim())return;chatMessages.push(['user',q.trim()]);let answer=/alert|malestar|inquiet|incómod/i.test(q)?'En el escenario de alerta se observan inquietud y movimientos repetitivos. Estos cambios no permiten determinar una causa. Puedes acercarte a María, preguntarle cómo se siente y revisar el contexto.':/sueño|descans|durm/i.test(q)?'En este ejemplo, María descansó 7 horas y 20 minutos. Su periodo de descanso se muestra dentro de su rutina habitual. Puedes ver el registro de las 06:24 en el historial.':'Hoy María desayunó a las 09:48, caminó por la sala y se levantó del sofá a las 10:32. Su actividad más reciente aparece como habitual. Puedes consultar cada momento en el historial.';chatMessages.push(['assistant',answer]);render();document.querySelector('#question').focus()}
function assistant(){return heading('Un poco más de claridad','Asistente Cerca · Conversación de demostración')+`<section class="card chat"><div class="card-heading"><h2 style="display:flex;gap:12px;align-items:center"><span class="ai-icon">${ico('spark')}</span> Estoy aquí para orientarte</h2><span class="badge">Demo</span></div><p class="muted">Te ayudo a entender la actividad registrada. No sustituyo una valoración profesional.</p><div class="chat-hints">${['¿Cómo está María hoy?','¿Por qué recibí esta alerta?','¿Cómo descansó?'].map(q=>`<button onclick="ask('${q}')">${q}</button>`).join('')}</div><div class="messages" aria-live="polite"><div class="message">Hola, Karol. Podemos revisar juntas el día de María. ¿Qué te gustaría saber?</div>${chatMessages.map(([role,text])=>`<div class="message ${role==='user'?'user':''}">${escapeText(text)}</div>`).join('')}</div><form onsubmit="event.preventDefault();ask(document.querySelector('#question').value)"><input id="question" aria-label="Tu pregunta para el asistente" placeholder="Escribe tu pregunta…" maxlength="500" autocomplete="off"><button class="button" aria-label="Enviar pregunta">${ico('send')}</button></form><p class="muted" style="font-size:10px;margin-top:12px;text-align:center">Respuestas predefinidas para presentar la experiencia.</p></section>`}
function device(){return heading('Dispositivo','Todo listo para acompañar su día.')+`<div class="grid"><section class="card"><div class="device-visual">${ico('device')}<h3>Cerca Home</h3><p class="subtitle">Sala de estar · Dispositivo 01</p><span class="badge" style="margin-top:15px">Conectado · Simulación</span></div><div class="setting"><div>Batería<small>Autonomía estimada: 18 horas</small></div><b>78 %</b></div><div class="meter"><span></span></div><div class="setting"><div>Señal Wi-Fi<small>Casa de María</small></div><span class="badge">Excelente</span></div><div class="setting"><div>Ubicación<small>Sala de estar</small></div>${ico('location')}</div></section><section class="card"><h2>Preferencias de cuidado</h2>${[['notifications','Avisos de actividad','Recibe los cambios relevantes.'],['sound','Sonido de alertas','Un aviso sonoro para eventos nuevos.'],['privacy','Modo de privacidad','Control sobre tu espacio de cuidado.']].map(([k,t,s])=>`<div class="setting"><div>${t}<small>${s}</small></div><button class="switch ${settings[k]?'on':''}" role="switch" aria-checked="${settings[k]}" aria-label="${t}" onclick="settings['${k}']=!settings['${k}'];render();notify('Preferencia actualizada en la demo')"></button></div>`).join('')}<p class="muted" style="margin:25px 0">Los controles modifican únicamente esta demostración. No hay conexión con un dispositivo físico.</p><button class="button secondary wide" onclick="modal('Tu dispositivo Cerca Home','Esta demo representa un dispositivo conectado con batería al 78 % y señal excelente. Los ajustes y el monitoreo son simulados para la presentación.')">¿Necesitas ayuda?</button></section></div>`}
function render(){let page=location.hash.slice(1)||'inicio';const active=page.startsWith('detalle')?'alertas':page==='monitoreo'?'inicio':page;document.querySelector('#navigation').innerHTML=nav.map(([id,icon,title])=>`<a href="#${id}" class="${id===active?'active':''}">${ico(icon)}${title}${id==='alertas'?'<span class="count">2</span>':''}</a>`).join('');document.querySelector('#mobile-nav').innerHTML=nav.filter(x=>x[0]!=='dispositivo').map(([id,icon,title])=>`<a href="#${id}" class="${id===active?'active':''}">${ico(icon)}${title}</a>`).join('');document.querySelector('#bell').innerHTML=ico('bell');document.querySelector('#breadcrumb').textContent='Mi espacio / '+(nav.find(x=>x[0]===active)?.[2]||'Inicio');const pages={inicio:home,alertas:alertPage,historial:history,persona:profile,asistente:assistant,dispositivo:device,monitoreo:monitor};const main=document.querySelector('#main');main.innerHTML=page.startsWith('detalle-')?detail(page.slice(8)):(pages[page]||home)();main.classList.remove('fade');void main.offsetWidth;main.classList.add('fade')}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});window.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.fullscreen-camera')?.classList.remove('fullscreen-camera')});render();
const faceIcon='<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M20 8H12a4 4 0 0 0-4 4v8M44 8h8a4 4 0 0 1 4 4v8M56 44v8a4 4 0 0 1-4 4h-8M8 44v8a4 4 0 0 0 4 4h8M22 23v6M42 23v6M33 23v13h-5M22 43c5 5 15 5 20 0"/></svg>';
let authTimer;let authMode='face';
function setAppInert(value){document.querySelectorAll('.sidebar,.shell,.mobile-nav').forEach(el=>el.inert=value)}
function lockApp(){clearTimeout(authTimer);authMode='face';document.querySelector('#auth-screen')?.remove();const auth=document.createElement('section');auth.id='auth-screen';auth.className='auth-screen';auth.setAttribute('aria-label','Acceso a Cerca');auth.innerHTML=`<div class="auth-story"><img class="auth-photo" src="assets/living-room.png" alt=""><a class="brand" href="#inicio"><img src="assets/logo.png" alt=""><span>cerca.</span></a><div><h2>La distancia cambia.<br>El cuidado permanece.</h2><p>Un pequeño vistazo. Un poco de tranquilidad. Una forma de estar cerca.</p><small>CERCA · CUIDAR SE SIENTE CERCA</small></div></div><div class="auth-panel"><div class="auth-content"><div class="brand"><img src="assets/logo.png" alt="Logo de Cerca"><span>cerca.</span></div><div id="auth-flow"></div><p class="auth-note">Prototipo de presentación<br>Acceso simulado. No se usa la cámara ni se recopilan datos biométricos.</p></div></div>`;document.body.appendChild(auth);setAppInert(true);drawAuth()}
function drawAuth(){clearTimeout(authTimer);document.querySelector('#auth-flow').innerHTML=authMode==='face'?`<div class="face-frame" id="face-frame">${faceIcon}</div><h1>Qué bueno tenerte cerca.</h1><p class="subtitle">Hola, Karol. Entra a tu espacio de cuidado<br>de forma sencilla y segura.</p><div class="auth-status" id="auth-status" role="status">Tu tranquilidad empieza aquí.</div><button class="button wide" id="face-button" onclick="scanFace()">${faceIcon} Entrar con Face ID</button><div class="auth-separator"></div><button class="link" onclick="authMode='code';drawAuth()">Usar código de acceso</button>`:`<div class="face-frame">${ico('device')}</div><h1>Tu código de acceso</h1><p class="subtitle">Para esta presentación, usa <b>123456</b>.</p><form onsubmit="event.preventDefault();verifyCode()"><input class="auth-code" id="access-code" aria-label="Código de acceso de seis dígitos" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="off"><div class="auth-status" id="auth-status" role="status"></div><button class="button wide">Entrar a Cerca</button></form><div class="auth-separator"></div><button class="link" onclick="authMode='face';drawAuth()">Volver a Face ID</button>`;if(authMode==='code')document.querySelector('#access-code').focus()}
function scanFace(){const b=document.querySelector('#face-button');b.disabled=true;document.querySelector('#face-frame').classList.add('scanning');document.querySelector('#auth-status').textContent='Reconociendo tu rostro…';authTimer=setTimeout(()=>{document.querySelector('#face-frame').className='face-frame success';document.querySelector('#face-frame').innerHTML=ico('check');document.querySelector('#auth-status').textContent='Identidad confirmada. Bienvenida, Karol.';authTimer=setTimeout(unlockApp,850)},1700)}
function verifyCode(){if(document.querySelector('#access-code').value==='123456')unlockApp();else{document.querySelector('#auth-status').textContent='El código de esta demo es 123456.';document.querySelector('#access-code').select()}}
function unlockApp(){document.querySelector('#auth-screen').remove();setAppInert(false);go('inicio');document.querySelector('#bell').focus();notify('Bienvenida, Karol')}
const lockButton=document.createElement('button');lockButton.className='icon-button lock-button';lockButton.setAttribute('aria-label','Bloquear y volver a mostrar Face ID');lockButton.title='Volver al acceso Face ID';lockButton.innerHTML=faceIcon;lockButton.onclick=lockApp;document.querySelector('.top-actions').prepend(lockButton);lockApp();
